from pathlib import Path
import re
p=Path('dist/index.html');s=p.read_text()
start=s.index('<main>');end=s.index('</main>')
oldmain=s[start+6:end]
work=re.search(r'<section id="work".*?</section>',oldmain,re.S).group()
services=re.search(r'<section class="section home-services">.*?</section>',oldmain,re.S).group()
cta=re.search(r'<section class="page-cta panther-cta">.*?</section>',oldmain,re.S).group()
hero='''<section class="sequence" id="sequence" aria-label="Scroll through the Panther cinematic experience"><div class="sequence-stage"><div class="seq-grain" aria-hidden="true"></div><div class="seq-vignette" aria-hidden="true"></div><div class="seq-face" aria-hidden="true"><img src="assets/panther-face.jpg" alt=""><i class="seq-lid left"></i><i class="seq-lid right"></i></div><canvas id="panther-rig" aria-label="Stylised Panther with articulated walking motion"></canvas><div class="claw-slashes" aria-hidden="true"><i></i><i></i><i></i></div><div class="seq-teeth" aria-hidden="true"><svg viewBox="0 0 1000 650"><defs><linearGradient id="tooth-metal" x1="0" x2="1"><stop stop-color="#121315"/><stop offset=".3" stop-color="#7b7c80"/><stop offset=".45" stop-color="#f4f3eb"/><stop offset=".53" stop-color="#9d9e9e"/><stop offset=".8" stop-color="#262729"/><stop offset="1" stop-color="#08090a"/></linearGradient></defs><path d="M80 -30 C200 20 260 5 300 -20 C287 160 235 330 190 385 C202 210 142 92 80 -30Z"/><path d="M920 -30 C800 20 740 5 700 -20 C713 160 765 330 810 385 C798 210 858 92 920 -30Z"/><path d="M145 680 C220 605 245 507 220 447 C280 507 320 597 300 680Z"/><path d="M855 680 C780 605 755 507 780 447 C720 507 680 597 700 680Z"/></svg></div><div class="seq-copy" data-chapter="0"><span class="seq-kicker">PANTHER PRODUCTIONS / INDEPENDENT CREATIVE STUDIO</span><h1>FOLLOW<br>THE <em>INSTINCT.</em></h1><p>Some stories ask for attention.<br>Ours hunt for it.</p></div><div class="seq-copy" data-chapter="1"><span class="seq-kicker">01 / THE PURSUIT</span><h2>BUILT<br>TO <em>PURSUE.</em></h2><p>Every move has a purpose.<br>Every frame has a point of view.</p></div><div class="seq-copy" data-chapter="2"><span class="seq-kicker">02 / THE EDGE</span><h2>LEAVE<br>A <em>MARK.</em></h2><p>Sharp ideas. Fearless craft.<br>Nothing here by accident.</p></div><div class="seq-copy" data-chapter="3"><span class="seq-kicker">03 / THE FRAME</span><h2>ALL<br><em>INSTINCT.</em></h2><a href="work.html" class="seq-cta">ENTER OUR WORLD <span>↗</span></a></div><div class="seq-top"><span>FILM · PRODUCTION · POST</span><button id="seq-motion">MOTION ON ◉</button></div><div class="seq-bottom"><span id="chapter-name">00 — THE AWAKENING</span><div class="seq-progress"><i></i></div><span class="scroll-prompt">SCROLL TO DIRECT <b>↓</b></span></div><div class="frame-number" aria-hidden="true">F / <span id="frame-count">0000</span></div></div></section>'''
intro='''<section class="manifesto"><div class="eyebrow">THE INSTINCT BEHIND THE IMAGE</div><h2>WE DON’T DO<br><span>BACKGROUND NOISE.</span></h2><div class="manifesto-bottom"><p>From an idea you can’t shake to a frame you won’t forget. Production, film, editing, brand shoots, marketing and film investment — all driven by one instinct.</p><a href="studio.html" class="text-link">INSIDE PANTHER ↗</a></div></section>'''
s=s[:start]+'<main>'+hero+intro+work+services+cta+s[end:]
s=s.replace('<script src="app.js"></script>','<script src="app.js"></script><script src="cinematic.js"></script>')
p.write_text(s)
# Drop the previous sliding animal treatment everywhere; retain the identity portraits on inner pages.
for p in Path('dist').glob('*.html'):
 t=p.read_text();t=re.sub(r'<div class="prowl-shadow".*?</div>','',t,flags=re.S);p.write_text(t)
